import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const whiteMagicPhysicalScenarios={'white-light-ordinary':'a2-p14-r1c2','white-light-dedicated':'a2-p14-r1c2','white-ring-ordinary':'a2-p14-r1c3','white-ring-dedicated':'a2-p14-r1c3','white-dance-ordinary':'a2-p14-r2c1','white-dance-dedicated':'a2-p14-r2c1','white-light-counter':'a2-p14-r1c2'} as const;
export type WhiteMagicPhysicalScenario=keyof typeof whiteMagicPhysicalScenarios;
export function isWhiteMagicPhysicalScenario(name:string):name is WhiteMagicPhysicalScenario{return Object.hasOwn(whiteMagicPhysicalScenarios,name);}
export function whiteMagicPhysicalMode(name:WhiteMagicPhysicalScenario){const light=name.includes('-light-'),dance=name.includes('-dance-'),dedicated=name.endsWith('-dedicated')||name.endsWith('-counter');return {card:whiteMagicPhysicalScenarios[name],light,dance,ring:!light&&!dance,dedicated,use:light?5:dance?7:6,effect:light?(dedicated?6:5):dance?(dedicated?9:7):dedicated?7:6,damage:light?6:dance&&dedicated?15:10,name:light?'白光':dance?'天舞':'白輪'};}
export function makeWhiteMagicPhysicalScenario(name:WhiteMagicPhysicalScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;follower?:'none'|'dead-knight'|'guardian'}={}){
 const m=whiteMagicPhysicalMode(name),counter=name.endsWith('-counter');let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string],owner=counter?b:a;for(const [i,p] of players.entries())assignCharacter(s,p.id,counter?['魔導王ガイナス',options.owner??'白魔術師シェリム','魔聖母ディア','侍大将のシン'][i]!: [options.owner??'白魔術師シェリム','黒騎士ガーウィン','魔聖母ディア','魔導王ガイナス'][i]!);for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit=20+6-gameStats(s,p.id).spirit;}s.players[owner]!.permanent!.magic_level=20+(options.level??m.use)-gameStats(s,owner).magic_level;
 const donor=counter?a:b,front=options.follower==='none'?null:takeCard(s,donor,options.follower==='dead-knight'?'デス・ナイト':options.follower==='guardian'?'守護者':'闇の聖女'),rear=options.follower===undefined?takeCard(s,donor,'スケルトン'):null,metal=options.follower==='none'?null:takeCard(s,c,'メタルゴーレム'),water=options.follower==='none'?null:takeCard(s,c,'水竜'),keep=[takeCard(s,owner,m.card),takeCard(s,a,'必勝の祈り'),takeCard(s,b,'a2-p06-r1c1'),takeCard(s,b,'a2-p05-r3c1'),takeCard(s,b,'a2-p07-r1c1'),takeCard(s,d,'命運凶変'),...[front,rear,metal,water].filter((x):x is string=>!!x)];if(counter)keep.push(takeCard(s,a,'a2-p15-r3c2'));for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(1)},r=transition(s,input,e);if(!r.ok)throw Error(`WHITE_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('WHITE_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('WHITE_IDS');}
 for(const p of players){for(const cardInstanceId of (p.id===donor?[front,rear]:p.id===c?[metal,water]:[]).filter((x):x is string=>!!x))act(p.id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});act(p.id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});return s;
}
